import MainNavigation from '../components/MainNavigation.vue';
export default {
  name: 'ContactUsPage',
  components: {
    MainNavigation
  },
  data() {
    return {
      form: {
        name: '',
        phone: '',
        school: '',
        content: ''
      },
      rules: {
        name: [{
          required: true,
          message: '请输入姓名',
          trigger: 'blur'
        }],
        phone: [{
          required: true,
          message: '请输入电话',
          trigger: 'blur'
        }],
        school: [{
          required: true,
          message: '请输入就读学校',
          trigger: 'blur'
        }],
        content: [{
          required: true,
          message: '请输入留言内容',
          trigger: 'blur'
        }]
      }
    };
  },
  methods: {
    submitForm(formName) {
      this.$refs[formName].validate(valid => {
        if (valid) {
          this.$message({
            message: '留言提交成功！',
            type: 'success'
          });
          this.$refs[formName].resetFields();
        } else {
          return false;
        }
      });
    }
  }
};
